    "loop": false,
    "note": "地底噴火：地表の亀裂が左から右へ赤熱し、四箇所から高さの異なる火柱が順番に突き上がる。個別の爆炎・黒煙・溶岩片・重なり合う地表衝撃波。",
    "body": "return eruptionRevised(p,t,q,3.);"
