  "271": {
    "duration": 0.43333333333333335,
    "loop": false,
    "note": "巨大氷柱と同じ白い反射面・青い陰影・内部の濁りを持つ小型の氷晶弾。左から右へ従来の3倍速で飛び、着弾時に結晶片へ砕ける。",
    "body": "if(q<=0.||q>=1.)return vec4(0.);\nvec2 a0=vec2(-.65,0.),b0=vec2(.60,0.);\nfloat flight=phase(q,.10,.69);\nvec2 c=mix(a0,b0,flight);\nfloat bodyFade=1.-smoothstep(.65,.72,q);\nvec4 v=vec4(0.);\nfor(int i=0;i<1;i++){\n float k=2.;\n float tall=.34,halfW=.095,lean=.012;\n float grow=swift(phase(q,0.,.12));\n if(grow<.008)continue;\n vec2 base=c-vec2(.18,0.);\n vec2 pp=vec2(p.y-base.y,p.x-base.x);\n float y=pp.y/tall;\n float axis=lean*y+.022*sin(y*6.+k);\n float x=pp.x-axis;\n float leftWidth=halfW*mix(1.0,.68,smoothstep(.04,.68,y));\n float rightWidth=halfW*mix(.91,.58,smoothstep(.08,.72,y));\n float point=1.-smoothstep(.66,1.005,y);\n leftWidth*=point;rightWidth*=point;\n float silhouette=(1.-smoothstep(leftWidth-.007,leftWidth+.004,-x))*(1.-smoothstep(rightWidth-.007,rightWidth+.004,x));\n silhouette*=smoothstep(-.012,.009,y)*(1.-smoothstep(.994,1.004,y));\n // Local ground clipping gives a solid rooted base throughout the emergence.\n silhouette*=1.-smoothstep(grow-.018,grow+.018,y);\n if(silhouette<.001)continue;\n float nx=x/max(.006,x<0.?leftWidth:rightWidth);\n float ridge=-.12+.14*sin(y*7.+k*.8);\n float split=smoothstep(ridge-.012,ridge+.012,nx);\n float n=fb(vec2(nx*3.2+k*4.7,y*9.));\n float grain=noise(vec2(nx*18.+k*3.,y*34.));\n vec3 shadow=vec3(.23,.46,.65),mid=vec3(.54,.78,.90),lit=vec3(.85,.96,1.);\n vec3 col=mix(shadow,mid,.38+.42*n);\n col=mix(col,lit,split*.63);\n // Thin white ridge, irregular reflected light patches, and internal cloudy ice.\n float streak=1.-smoothstep(.018,.065,abs(nx-ridge-.045*sin(y*14.+k)));\n float inner=fb(vec2(nx*6.+y*2.+k*4.,y*12.));\n float white=smoothstep(.58,.81,inner+.16*grain);\n col=mix(col,vec3(.96,.99,1.),sat(white*.67+streak*.48));\n float edge=smoothstep(.83,.99,abs(nx));\n col=mix(col,vec3(.76,.92,.99),edge*.62);\n float crack=0.;\n for(int j=0;j<3;j++){\n  float n0=float(j),h=.22+n0*.23+.045*hash(vec2(k,n0));\n  vec2 a=vec2(-.65,h),b=vec2(-.10,h+.085),c=vec2(.42,h+.038);\n  float z=min(seg(vec2(nx,y),a,b),seg(vec2(nx,y),b,c));\n  crack=max(crack,(1.-smoothstep(.008,.026,z))*.38);\n }\n col=mix(col,vec3(.38,.62,.77),crack);\n v=over(v,vec4(col,silhouette*bodyFade*.97));\n}\nreturn over(v,iceBurst(p,b0,phase(q,.69,1.),.25,5.,8.));"
  },
