    "body": "float waterForm=1.;float wt=fract(t);float g=smoothstep(0.,.83,waterForm);if(g<.005)return vec4(0.);\nvec2 c=vec2(.23,0.);vec2 z=p-c;z=vec2(z.x+.09*z.y,z.y)/vec2(.40*g,.77*g);\nfloat r=length(z),a=atan(z.y,z.x);float n=fb(z*6.+dir2(wt*TAU)*.52);\nfloat spiral=.5+.5*cos(3.*a-17.*r-wt*TAU*3.+(n-.5)*2.1);\nfloat band=smoothstep(.28,.85,spiral),foam=smoothstep(.78,.98,spiral)*(.45+.55*n);\nfloat edge=1.-smoothstep(.90,1.06,r+(n-.5)*.13);\nfloat hole=smoothstep(.06,.19,r);\nfloat rim=(1.-smoothstep(.028,.105,abs(r-.91+(n-.5)*.09)));\nvec4 v=waterColor(edge*hole*(.18+.66*band)*g,.25+.63*n,sat(foam*.88+rim*.5));\nv=over(v,waterColor(rim*edge*hole*(.40+.42*n)*g,.86,.90));\nfor(int i=0;i<18;i++){float k=float(i),ang=k*TAU/18.+wt*TAU*2.;float f=fract(wt+hash(vec2(k,11.)));vec2 pos=c+dir2(ang)*vec2(.40,.77)*g*(.84+.16*f);float sz=.009+.012*hash(vec2(k,8.));vec4 w=liquidBall(p,pos,sz,wt);w.a*=sin(3.14159*f)*g*.65;v=over(v,w);}\nreturn v;"
