    "body": "if(q<=0.||q>=1.)return vec4(0.);\nvec2 a=vec2(-.65,.05),b=vec2(.59,-.05);float f=phase(q,.12,.63),g=swift(phase(q,0.,.12));vec2 c=mix(a,b,f)+vec2(0.,.13*sin(3.14159*f));\nvec4 v=acidDrop(p,c,vec2(1.,-.12),.14*g,.085*g,12.);v.a*=1.-smoothstep(.59,.66,q);\nfor(int i=0;i<4;i++){float k=float(i);vec4 w=acidDrop(p,c-vec2(.10+.045*k,.018*sin(k)),vec2(1.,0.),.038,.016,12.+k);w.a*=gate(q,.12,.66)*(1.-k*.18);v=over(v,w);}\nv=over(v,acidSplash(p,b,phase(q,.63,1.),.23,4.));vec4 pool=toxPool(p,b,phase(q,.63,.85),.20,t,1.);pool.a*=1.-smoothstep(.83,1.,q);return over(v,pool);"
