    "body": "float toxFormation=1.;float time=fract(t);vec4 v=vec4(0.);\nfor(int i=0;i<8;i++){float k=float(i),a=k*2.39996+time*TAU;float g=smoothstep(.02+k*.045,.38+k*.045,toxFormation);vec2 c=vec2(cos(a)*.43,-.38+sin(a)*.105)+vec2(.06*sin(time*TAU*2.+k),.05*sin(a));vec4 w=toxCloud(p,c,vec2(.29,.20),time,k+14.,0.);w.a*=g*.72;v=over(v,w);}\nreturn v;"
