    "body": "if(q<=0.||q>=1.)return vec4(0.);vec2 root=vec2(0.,-.57);vec4 v=vec4(0.);\nfor(int i=0;i<16;i++){float k=float(i),born=.08+k*.022,f=phase(q,born,born+.43);if(f<=0.||f>=1.)continue;vec2 c=vec2(.14*(hash(vec2(k,11.))-.5)+.055*sin(f*8.+k),.76-1.32*f*f);vec4 w=acidDrop(p,c,vec2(0.,-1.),.13+.08*f,.075+.025*hash(vec2(k,9.)),k);w.a*=smoothstep(0.,.08,f)*(1.-smoothstep(.89,1.,f));v=over(v,w);}\nfloat g=phase(q,.47,.84);vec4 pool=toxPool(p,root,g,.44,t,1.);pool.a*=1.-smoothstep(.84,1.,q);v=over(v,pool);\nfor(int i=0;i<3;i++){float k=float(i);v=over(v,acidSplash(p,root,phase(q,.47+k*.11,.78+k*.10),.37,17.+k));}return v;"
