    "body": "if(q<=0.||q>=1.)return vec4(0.);vec4 v=vec4(0.);\nfor(int i=0;i<5;i++){float k=float(i);vec4 w=toxCloud(p,vec2((k-2.)*.26,.64+.05*sin(k)),vec2(.32,.16),t,21.+k,1.);w.a*=gate(q,0.,.91)*.65;v=over(v,w);}\nfor(int i=0;i<28;i++){float k=float(i),wave=floor(k/7.),born=.12+wave*.15+hash(vec2(k,4.))*.035,f=phase(q,born,born+.28);float x=(hash(vec2(k,8.))-.5)*1.48;vec2 c=vec2(x+.04*(1.-f),.53-1.05*f);if(f>0.&&f<1.){vec4 w=acidDrop(p,c,vec2(-.08,-1.),.068,.016,19.+k);w.a*=sin(3.14159*f);v=over(v,w);}float h=phase(q,born+.28,born+.39);if(h>0.&&h<1.){vec2 root=vec2(x,-.52);float z=ring(p,root,vec2(.025+.065*h,(.025+.065*h)*.34),.004)*sin(3.14159*h);v=over(v,vec4(toxPalette(.8,1.),sat(z)*.50));}}\nvec4 pool=toxPool(p,vec2(0.,-.53),phase(q,.40,.85),.77,t,1.);pool.a*=.46*(1.-smoothstep(.82,1.,q));return over(v,pool);"
