    "body": "if(q<=0.||q>=1.)return vec4(0.);vec2 root=vec2(0.,-.30);vec4 v=vec4(0.);\nfloat pre=gate(q,0.,.39);vec4 core=toxCloud(p,root,vec2(.15+.12*phase(q,0.,.30)),t,11.,0.);core.a*=pre;v=over(v,core);\nfloat h=phase(q,.30,1.),g=1.-pow(1.-h,3.);\nfor(int i=0;i<10;i++){float k=float(i),a=k*2.39996;vec2 c=root+dir2(a)*vec2(.56,.50)*g+vec2(0.,.24*g);vec4 w=toxCloud(p,c,vec2(.12+.22*g,.11+.21*g),t,k+30.,0.);w.a*=smoothstep(0.,.10,h)*(1.-smoothstep(.50,1.,h))*.87;v=over(v,w);}\nfloat z=ring(p,vec2(0.,-.51),vec2(.04+.76*g,(.04+.76*g)*.34),.009)*sin(3.14159*h);\nreturn over(v,vec4(toxPalette(.72,0.),sat(z)*.55));"
