    "body": "float toxFormation=1.;float time=fract(t);vec2 root=vec2(0.,-.48);float g=smoothstep(.03,.67,toxFormation);vec4 v=toxPool(p,root,g,.81,time,0.);\nfor(int i=0;i<12;i++){float k=float(i),a=k*2.39996+time*TAU;float f=fract(time+hash(vec2(k,3.)));vec2 c=root+dir2(a)*vec2(.64,.64*.34)*(.55+.35*hash(vec2(k,8.)))+vec2(0.,.25*f);vec4 w=toxCloud(p,c,vec2(.20,.15+.09*f),time,k+51.,0.);w.a*=sin(3.14159*f)*smoothstep(.15+k*.02,.55+k*.02,toxFormation)*.83;v=over(v,w);}\nvec4 z=toxBubbles(p,root,time,1.38,.48,20.,0.);z.a*=smoothstep(.35,.88,toxFormation);return over(v,z);"
