    "body": "if(q<=0.||q>=1.)return vec4(0.);vec2 root=vec2(-.73,0.);vec4 v=vec4(0.);\nfor(int i=0;i<16;i++){float k=float(i),born=.07+.030*k,f=phase(q,born,born+.47);if(f<=0.||f>=1.)continue;float lane=hash(vec2(k,14.))*2.-1.;vec2 c=root+vec2(1.47*f,lane*(.035+.34*f)+.04*sin(f*9.+k));vec4 w=toxCloud(p,c,vec2(.13+.21*f,.065+.15*f),t,k+60.,1.);w.a*=sin(3.14159*f)*.86;v=over(v,w);}\nfor(int i=0;i<20;i++){float k=float(i),born=.08+.022*k,f=phase(q,born,born+.40);if(f<=0.||f>=1.)continue;vec2 c=root+vec2(1.53*f,(hash(vec2(k,23.))-.5)*(.06+.62*f));vec4 w=acidDrop(p,c,vec2(1.,0.),.045,.018,k);w.a*=sin(3.14159*f)*.9;v=over(v,w);}return v;"
