    "body": "if(q<=0.||q>=1.)return vec4(0.);vec4 v=vec4(0.);\nfloat g=swift(phase(q,.12,.44)),e=1.-smoothstep(.79,1.,q);\nfor(int i=0;i<10;i++){float k=float(i),a=k*2.39996+q*3.;vec2 c=dir2(a)*vec2(.46,.57)*(1.-.68*g);vec4 w=toxCloud(p,c,vec2(.20,.20),t,k+70.,0.);w.a*=gate(q,0.,.76)*.78;v=over(v,w);}\nfor(int i=0;i<7;i++){float k=float(i),a=k*2.39996;vec2 c=dir2(a)*vec2(.22,.44);vec4 w=toxCloud(p,c,vec2(.14,.19),t,k+77.,0.);w.a*=g*e*.85;v=over(v,w);}\nvec4 z=toxBubbles(p,vec2(0.,-.48),t*2.,.62,1.04,22.,0.);z.a*=gate(q,.32,1.);return over(v,z);"
