    "body": "if(q<=0.||q>=1.)return vec4(0.);vec2 a=vec2(-.73,0.),b=vec2(.64,0.);float f=swift(phase(q,.31,.40)),tail=swift(phase(q,.65,.78)),e=gate(q,.30,.80);vec4 v=vec4(toxPalette(.9,1.),sat(ball(p,a,.09+.10*phase(q,0.,.28))*gate(q,0.,.39)));\nif(f>tail){vec2 s=mix(a,b,tail),z=mix(a,b,f);float dist=seg(p,s,z),n=fb(vec2(p.x*17.-t*7.,p.y*33.));float outer=(1.-smoothstep(.025,.12,dist+(n-.5)*.015))*e;float inner=(1.-smoothstep(.009,.033,dist))*e;v=over(v,vec4(toxPalette(.38+.48*n,1.),outer*.7));v=over(v,vec4(toxPalette(.94,1.),inner));}\nfloat h=phase(q,.40,1.);vec4 m=toxCloud(p,b+vec2(0.,.20*h),vec2(.18+.12*h,.20+.12*h),t,71.,1.);m.a*=gate(q,.40,1.)*.85;v=over(v,m);return over(v,acidSplash(p,b,h,.30,11.));"
