    "body": "if(q<=0.||q>=1.)return vec4(0.);vec2 a=vec2(-.72,0.),b=vec2(.59,-.06);vec4 v=vec4(0.);\nfloat chargeG=phase(q,.02,.38),pre=gate(q,0.,.45);\nfor(int i=0;i<8;i++){float k=float(i),ang=k*TAU/8.+chargeG*3.;vec2 c=a+dir2(ang)*(.34*(1.-chargeG));vec4 w=acidDrop(p,c,dir2(ang),.055,.028,k);w.a*=pre;v=over(v,w);}\nv=over(v,vec4(toxPalette(.96,1.),sat(ball(p,a,.10+.16*chargeG)*pre)));\nfloat head=swift(phase(q,.37,.48)),tail=swift(phase(q,.72,.86)),e=gate(q,.36,.88);\nif(head>tail){vec2 st=mix(a,b,tail),en=mix(a,b,head);float d=seg(p,st,en),n=fb(vec2(p.x*10.-t*9.,p.y*15.));float pulse=.75+.25*sin(q*TAU*9.);float broad=(1.-smoothstep(.08,.24,d+(n-.5)*.075))*e;float hot=(1.-smoothstep(.024,.075*pulse,d))*e;v=over(v,vec4(toxPalette(.28+.53*n,1.),broad*.94));v=over(v,vec4(toxPalette(.98,1.),hot));}\nfor(int i=0;i<8;i++){float k=float(i),born=.47+k*.035,h=phase(q,born,born+.27);if(h<=0.||h>=1.)continue;vec2 c=b+vec2((hash(vec2(k,29.))-.5)*.31,.42*h);vec4 w=toxCloud(p,c,vec2(.13+.11*h,.14+.12*h),t,k+91.,1.);w.a*=sin(3.14159*h);v=over(v,w);}\nvec2 ground=b+vec2(-.13,-.42);vec4 pool=toxPool(p,ground,phase(q,.48,.86),.36,t,1.);pool.a*=1.-smoothstep(.83,1.,q);v=over(v,pool);\nfor(int i=0;i<3;i++){float k=float(i);v=over(v,acidSplash(p,b,phase(q,.48+k*.09,.72+k*.10),.29,31.+k));}return v;"
