const poisonHelpers="float swift(float f){return 1.-pow(1.-sat(f),3.);}\n\nvec3 toxPalette(float z,float acid){\n z=sat(z);\n vec3 low=mix(vec3(.20,.045,.31),vec3(.24,.39,.045),acid);\n vec3 mid=mix(vec3(.57,.22,.77),vec3(.647,.847,.263),acid);\n vec3 high=mix(vec3(.88,.63,1.),vec3(.93,1.,.63),acid);\n return mix(mix(low,mid,smoothstep(0.,.62,z)),high,smoothstep(.55,1.,z));\n}\nvec4 toxCloud(vec2 p,vec2 c,vec2 r,float t,float seed,float acid){\n vec2 v=(p-c)/max(r,vec2(.015));if(length(v)>1.55)return vec4(0.);\n float n=fb(v*3.9+dir2(TAU*t+seed)*.48+seed);\n float d=length(v)+(n-.5)*.53;\n float a=(1.-smoothstep(.48,1.12,d))*(.40+.50*n);\n return vec4(toxPalette(.27+.60*n+.12*v.y,acid),sat(a));\n}\nvec4 acidDrop(vec2 p,vec2 c,vec2 axis,float l,float w,float seed){\n vec2 d=normalize(axis),s=vec2(-d.y,d.x),v=p-c;\n vec2 uv=vec2(dot(v,d)/max(.01,l),dot(v,s)/max(.008,w));\n float n=fb(uv*5.+seed);float dist=length(uv*vec2(.92,1.));\n float a=1.-smoothstep(.89,1.06,dist+(n-.5)*.14);\n float shine=exp(-length((uv-vec2(.14,.32))*vec2(2.,4.))*1.8);\n return vec4(toxPalette(.45+.37*n+.32*shine,1.),a*.95);\n}\nvec4 toxPool(vec2 p,vec2 root,float g,float radius,float t,float acid){\n if(g<=0.)return vec4(0.);\n vec2 uv=(p-root)/vec2(radius,radius*.34);\n float n=fb(uv*6.+dir2(t*TAU)*.30);\n float d=length(uv)+(n-.5)*.17;\n float a=(1.-smoothstep(g-.07,g+.045,d))*smoothstep(0.,.09,g);\n float ripple=(1.-smoothstep(.015,.075,abs(d-g+.05)))*.25;\n return vec4(toxPalette(.32+.50*n+ripple,acid),a*.72);\n}\nvec4 acidSplash(vec2 p,vec2 root,float f,float radius,float seed){\n if(f<=0.||f>=1.)return vec4(0.);\n vec4 v=vec4(0.);\n for(int i=0;i<12;i++){float k=float(i),u=2.*hash(vec2(k,seed))-1.;\n float speed=.55+.45*hash(vec2(k,seed+2.));\n vec2 c=root+vec2(u*radius*f*speed,(.10+.24*hash(vec2(k,seed+5.)))*4.*f*(1.-f));\n vec4 w=acidDrop(p,c,vec2(u*.5,.7-f),.025+.018*speed,.015,seed+k);\n w.a*=sin(3.14159*f);v=over(v,w);}\n return v;\n}\nvec4 toxBubbles(vec2 p,vec2 center,float t,float width,float height,float count,float acid){\n vec4 v=vec4(0.);\n for(int i=0;i<22;i++){float k=float(i);if(k>=count)break;\n float f=fract(t+hash(vec2(k,7.)));\n vec2 c=center+vec2((hash(vec2(k,11.))-.5)*width+.045*sin(TAU*f+k),height*f);\n float r=.016+.030*hash(vec2(k,13.));float d=length(p-c);\n float edge=(1.-smoothstep(.003,.010,abs(d-r)))*.60;\n float hi=(1.-smoothstep(.002,.012,length(p-c-vec2(-r*.30,r*.38))));\n v=over(v,vec4(toxPalette(.70+.25*hi,acid),sat(edge+hi*.6)*sin(3.14159*f)));\n }return v;\n}\n";
