const forceDefenseHelpers="\nfloat fEase(float f){return 1.-pow(1.-sat(f),3.);}\nvec4 fColor(float a,float brightness){return vec4(mix(uColor,vec3(.93,.98,1.),sat(brightness)),sat(a));}\nfloat fEdge(float d,float w){return 1.-smoothstep(w*.45,w*1.5,abs(d));}\nfloat fPoly(vec2 p,float n,float angle){float a=atan(p.y,p.x)+angle;return length(p)*cos(floor(.5+a*n/TAU)*TAU/n-a);}\nvec4 fPane(vec2 p,vec2 center,vec2 radius,float angle,float power,float sides){\n vec2 v=p-center;float c=cos(angle),s=sin(angle);v=vec2(c*v.x+s*v.y,-s*v.x+c*v.y)/max(radius,vec2(.015));\n float d=fPoly(v,sides,TAU/(sides*2.));float mask=1.-smoothstep(.98,1.02,d);\n float edge=fEdge(d-1.,.018);float stripe=fEdge(v.x+v.y*.38-.12,.025)*mask;\n return fColor(power*(mask*.12+edge*.88+stripe*.16),.22+edge*.7);\n}\nvec4 fBubble(vec2 p,vec2 center,vec2 radius,float t,float strength,float kind){\n vec2 v=(p-center)/max(radius,vec2(.015));float d=length(v),a=atan(v.y,v.x);\n float rim=fEdge(d-1.,.025),inside=1.-smoothstep(.96,1.02,d);\n float shine=pow(max(0.,cos(a-2.05)),9.)*fEdge(d-.92,.042);\n float wave=fEdge(d-.81-.05*sin(3.*a+t*TAU),.015)*kind;\n return fColor(strength*(inside*.065+rim*.78+shine*.65+wave*.31),.30+rim*.65+shine*.3);\n}\nvec4 fFloor(vec2 p,vec2 c,float radius,float t,float strength){\n vec2 v=(p-c)/max(vec2(radius,radius*.34),vec2(.015));float d=length(v),a=atan(v.y,v.x);\n float z=fEdge(d-1.,.018)+fEdge(d-.77,.014)*.55+fEdge(d-.89,.055)*fEdge(sin(a*12.),.27)*.50;\n return fColor(strength*(z+.075*(1.-smoothstep(.96,1.,d))),.4+z*.35);\n}\nvec4 fWave(vec2 p,vec2 root,float f,float radius,float squash){\n if(f<=0.||f>=1.)return vec4(0.);float r=.035+radius*fEase(f);vec2 v=(p-root)/vec2(1.,squash);float d=length(v);\n float z=fEdge(d-r,.025+.018*f)+.28*fEdge(d-r+.075,.018);\n return fColor(z*sin(3.14159*f),.8);\n}\nvec4 fShard(vec2 p,vec2 c,float angle,float radius,float strength){\n vec2 v=p-c,ax=dir2(angle);v=vec2(dot(v,ax),dot(v,vec2(-ax.y,ax.x)))/max(.005,radius);\n float d=abs(v.x)+abs(v.y)*1.7;float a=(1.-smoothstep(.93,1.05,d));return fColor(a*strength,.35+.60*fEdge(d-1.,.12));\n}\n";
for(const r of records){const d=forceDefenseDetails[r.row];if(d)Object.assign(r,{note:'個別改修版：'+d.note,refined:true});}
function baseCode(r){const level=r.lv.toFixed(1),power=(.92+Math.max(0,r.lv-3)*.24).toFixed(2),seed=(r.row*.0137).toFixed(5);const constants="const float LEVEL="+level+", POWER="+power+", LOOP="+(r.loop?"1.":"0.")+", MAGIC_SEED="+seed+", FAMILY="+families[r.attribute].toFixed(1)+";\n";const d=fireDetails[r.row]||iceDetails[r.row]||waterDetails[r.row]||windDetails[r.row]||earthDetails[r.row]||lightDetails[r.row]||plantDetails[r.row]||poisonDetails[r.row]||forceDefenseDetails[r.row];if(d)return "// "+r.name+" / CS "+r.row+" / 個別改修版\n"+constants+header+(fireDetails[r.row]?(layerFireSoftRows.has(r.row)?(layerFireRows.has(r.row)?layerFireSoftHelpers:layerFireSoftExtendedHelpers):layerFireRows.has(r.row)?layerFireHelpers:layerFireExtendedRows.has(r.row)?layerFireExtendedHelpers:fireHelpers):iceDetails[r.row]?iceHelpers:waterDetails[r.row]?waterHelpers:windDetails[r.row]?windHelpers:earthDetails[r.row]?earthHelpers:lightDetails[r.row]?lightHelpers:plantDetails[r.row]?plantHelpers:poisonDetails[r.row]?poisonHelpers:forceDefenseHelpers)+"\nvec4 effect(vec2 p,float t,float q){"+d.body+"}\nvoid main(){vec2 p=(vUv-.5)*2.;p*=vec2(max(1.,uAspect),max(1.,1./uAspect));p/=max(.1,uSize);gl_FragColor=effect(p,uTime,uProgress);}";return "// "+r.name+" / "+r.attribute+" / CS "+r.row+" / 初期制作案\n"+constants+header+"\nvec4 effect(vec2 p,float t,float q){"+bodies[r.mode]+"}\n"+decoration+"\nvoid main(){vec2 p=(vUv-.5)*2.;p*=vec2(max(1.,uAspect),max(1.,1./uAspect));p/=max(.1,uSize);gl_FragColor=decorate(p,uTime,uProgress,effect(p,uTime,uProgress));}";}
// Match the approved CS234 flame temperature colors without altering silhouettes or motion.
const firePaletteRows=new Set([234,235,236,237,238,241,242,243,244,246,247,248,249,251,252,253,254,255,256,257,260,261,262,263]);
const firePaletteReplacements=[["vec4 lfColor(float z){return vec4(mix(uColor,uCore,smoothstep(.55,1.1,z)),sat(z));}","vec3 firePalette(float heat){\n heat=sat(heat);\n vec3 col=mix(vec3(.70,.055,.012),vec3(1.,.30,.018),smoothstep(.04,.60,heat));\n col=mix(col,vec3(1.,.76,.13),smoothstep(.45,.84,heat));\n return mix(col,vec3(1.,.96,.76),smoothstep(.74,1.03,heat)*.93);\n}\nvec4 lfColor(float z){return vec4(firePalette(z),sat(z));}"],["vec3 col=mix(uColor*.72,uColor,smoothstep(.05,.40,density));col=mix(col,uCore,smoothstep(.48,1.03,density)*.88);","vec3 col=firePalette(sat((1.-min(1.,abs(x+bend)/max(.08,width*cap))*.74)*(.53+.75*n+.18*detail)-.08*u));"],["vec3 c=mix(uColor*.83,uColor,smoothstep(.05,.4,density));c=mix(c,uCore,smoothstep(.58,1.05,density)*.78);","vec3 c=firePalette(sat(density*1.1));"]];
function code(r){const src=baseCode(r);return firePaletteRows.has(r.row)?firePaletteReplacements.reduce((v,[a,b])=>v.replace(a,b),src):src;}
// Activation and persistent variants share CS identity. Original loop source is retained verbatim.
const fireSceneExtra="vec4 denseBurst(vec2 p,vec2 c,float f,float r,float t,float seed){\n if(f<=0.||f>=1.)return vec4(0.);float g=fq(f),e=smoothstep(0.,.065,f)*(1.-smoothstep(.44,1.,f));vec4 v=vec4(0.);float rad=r*(.13+.72*g);\n for(int i=0;i<8;i++){float k=float(i),a=k*TAU/8.+hash(vec2(k,seed))*.45;vec2 b=c+dir2(a)*rad*.47;vec4 w=fm(p,b,rad*(.40+.16*hash(vec2(k,seed+1.))),t,k+seed);w.a*=e;v=over(v,w);}\n vec4 w=fm(p,c,rad*.76,t,seed+11.);w.a*=e;return over(v,w);\n}\nvec4 denseSmoke(vec2 p,vec2 c,vec2 r,float t,float seed){\n vec2 v=(p-c)/max(r,vec2(.01));float n=lfFlow(v*3.6+seed,vec2(.4,2.),t);float det=lfFlow(v*8.2+seed,vec2(.3,3.4),t);float d=length(v)+(n-.5)*.46;float a=(1.-smoothstep(.62,1.13,d))*(.83+.17*det);vec3 color=mix(vec3(.055,.047,.043),vec3(.27,.23,.20),sat((n-.28)*1.4+det*.23));return vec4(color,a);\n}\nvec4 rollingBlast(vec2 p,vec2 root,float f,float t,float huge){\n if(f<=0.||f>=1.)return vec4(0.);\n float g=fq(f),e=smoothstep(0.,.055,f)*(1.-smoothstep(.72,1.,f));vec4 v=vec4(0.);\n for(int i=0;i<10;i++){float k=float(i),j=hash(vec2(k,31.)),side=hash(vec2(k,11.))*2.-1.;float rise=phase(f,k*.018,.95);vec2 c=root+vec2(side*(.12+.41*g),(.18+.92*j)*g);vec2 r=vec2(.23+.17*j,.23+.15*j)*(.45+.55*g);vec4 w=denseSmoke(p,c,r,t,k+23.);w.a*=e*smoothstep(0.,.10,rise)*mix(1.,.18,huge);v=over(v,w);}\n for(int i=0;i<9;i++){float k=float(i),j=hash(vec2(k,72.)),side=hash(vec2(k,13.))*2.-1.;float u=phase(f,k*.027,.79+k*.016);vec2 c=root+vec2(side*(.05+.43*g),(.14+.86*j)*g);float rad=(.19+.20*j)*(.25+.75*fq(u));vec4 w=fm(p,c,rad,t,k+41.);float n=lfFlow((p-c)*19.+k,vec2(0.,4.),t);w.rgb=firePalette(sat((.86-.65*length(p-c)/max(.02,rad))+.33*n));w.a*=smoothstep(0.,.10,u)*(1.-smoothstep(.62,1.,u))*e;v=over(v,w);}\n for(int i=0;i<4;i++){float k=float(i),side=k<2.?-1.:1.,j=hash(vec2(k,53.));vec2 c=root+vec2(side*(.27+.20*j)*g,(.38+.54*j)*g);vec4 w=denseSmoke(p,c,vec2(.18,.22)*(.35+.65*g),t,k+81.);w.a*=smoothstep(.12,.38,f)*(1.-smoothstep(.78,1.,f))*.90*mix(1.,.20,huge);v=over(v,w);}\n return v;\n}\nvec4 eruptionScene(vec2 p,float t,float q,float big){\n if(q<=0.||q>=1.)return vec4(0.);vec2 a=vec2(0.,-.62);float ch=phase(q,.025,.34),g=fq(phase(q,.34,.51)),f=phase(q,.34,1.);vec4 v=vec4(0.);float z=0.;\n for(int i=0;i<7;i++){float k=float(i),side=mod(k,2.)*2.-1.,len=(.21+.36*hash(vec2(k,42.)))*mix(.72,1.,big)*ch;vec2 c=a+vec2(side*len,.04*(hash(vec2(k,21.))-.5));vec2 m=mix(a,c,.52)+vec2(0.,.052*sin(k*2.));z+=1.-smoothstep(.008,.026,seg(p,a,m));z+=1.-smoothstep(.008,.024,seg(p,m,c));}\n v=vec4(firePalette(.55+.40*ch),sat(z)*smoothstep(.02,.10,q)*(1.-smoothstep(.39,.69,q)));\n float width=mix(.25,.43,big),height=mix(.86,1.35,big);float e=fe(q,.33,1.);\n for(int i=0;i<7;i++){float k=float(i),side=hash(vec2(k,62.))*2.-1.,j=hash(vec2(k,17.)),u=phase(q,.35+k*.025,.96);vec2 c=a+vec2(side*width*(.4+.65*g),height*(.43+.49*j)*g+.06*u);vec4 w=denseSmoke(p,c,vec2(.20+.15*big,.25+.09*big)*(.33+.67*g),t,k+19.);w.a*=smoothstep(0.,.16,u)*(1.-smoothstep(.72,1.,u))*smoothstep(.34,.49,q);v=over(v,w);}\n for(int i=0;i<5;i++){float k=float(i),x=(k-2.)/2.;vec4 w=lfPlume(p,a+vec2(x*width*.28,0.),a+vec2(x*width*.9,height*g*(.70+.30*cos(k))),width*.74*g,t,k);w.a*=e;v=over(v,w);}\n return over(v,fl(p,a,f,mix(.44,.72,big),height,17.,mix(9.,15.,big)));\n}\n";
const eruptionRevisedExtra="// Shared napalm material, independently choreographed volcanic effects.\nvec4 eruptionCloud(vec2 p,vec2 root,float h,float t,vec2 scale,float opening){\n if(h<=0.||h>=1.)return vec4(0.);\n vec2 local=p-root;\n float wide=mix(opening,1.,smoothstep(.025,.65,sat(local.y/scale.y)));\n return napalmRoll(root+vec2(local.x/(scale.x*wide),local.y/scale.y),root,h,t);\n}\nvec4 eruptionColumn(vec2 p,vec2 root,float h,float t,float height,float width,float seed){\n if(h<=0.||h>=1.)return vec4(0.);\n vec2 v=p-root;\n float g=1.-pow(1.-phase(h,0.,.25),3.);\n float y=v.y/max(.015,height*g);\n if(y<-.03||y>1.18)return vec4(0.);\n float n=lfFlow(vec2(v.x*12.+seed,v.y*7.),vec2(0.,8.),t);\n float d=lfFlow(vec2(v.x*24.+seed,v.y*15.),vec2(0.,12.),t);\n float axis=(n-.5)*width*.65*smoothstep(.06,.6,y);\n float w=width*(.44+.56*smoothstep(.03,.75,y));\n float crossDist=abs(v.x-axis)/max(.015,w);\n float mass=(1.-smoothstep(.56,1.15,crossDist+(d-.5)*.5))*smoothstep(-.025,.055,y)*(1.-smoothstep(.76+.15*n,1.10,y));\n float env=smoothstep(0.,.045,h)*(1.-smoothstep(.47,.76,h));\n float hot=sat((.68+.45*n+.14*d)-.50*crossDist-.23*y);\n return vec4(firePalette(hot),sat(mass*env*(.68+.42*n)));\n}\nvec4 eruptionGround(vec2 p,vec2 root,float h,float radius){\n if(h<=0.||h>=1.)return vec4(0.);\n float g=1.-pow(1.-h,3.);\n float d=abs(length((p-root)/vec2(1.,.34))-(.025+radius*g));\n float z=(1.-smoothstep(.008,.025,d))*sin(3.14159*h);\n return vec4(firePalette(.75),z*.65);\n}\nvec4 eruptionRevised(vec2 p,float t,float q,float kind){\n if(q<=0.||q>=1.)return vec4(0.);\n vec2 root=vec2(0.,-.65);\n vec4 v=vec4(0.);\n if(kind<.5){\n  // CS249: one narrow vent, quick upward jet, compact rolling crown.\n  float pre=gate(q,.01,.25);float z=ball(p,root,.09+.045*phase(q,0.,.18));\n  v=vec4(firePalette(z),sat(z*pre));\n  float h=phase(q,.19,1.);\n  v=over(v,eruptionGround(p,root,phase(q,.19,.45),.36));\n  v=over(v,eruptionColumn(p,root,h,t,.94,.15,4.));\n  v=over(v,eruptionCloud(p,root,h,t,vec2(.46,.93),.40));\n  return over(v,fl(p,root,phase(q,.19,.93),.40,.81,17.,8.));\n }\n if(kind<1.5){\n  // CS255: broad fan of three overlapping eruptions, outward-leaning side jets.\n  for(int i=0;i<3;i++){\n   float k=float(i),side=k-1.;\n   vec2 vent=root+vec2(side*.25,0.);\n   float start=.22+.09*abs(side);\n   float pre=gate(q,.03,start+.04);float z=ball(p,vent,.10);\n   v=over(v,vec4(firePalette(z),sat(z*pre)));\n   float h=phase(q,start,1.);\n   if(h>0.&&h<1.){\n    vec2 warped=p-vec2(side*.26*max(0.,p.y-root.y),0.);\n    v=over(v,eruptionGround(p,vent,phase(q,start,start+.25),.34));\n    v=over(v,eruptionColumn(warped,vent,h,t,1.04-.25*abs(side),.17,12.+k));\n    v=over(v,eruptionCloud(warped,vent,h,t,vec2(.39,.93-.20*abs(side)),.64));\n    v=over(v,fl(p,vent,phase(q,start,.96),.27,.72-.12*abs(side),27.+k,7.));\n   }\n  }\n  return v;\n }\n if(kind<2.5){\n  // CS260: concentrated plasma-white core, massive column and a separate spreading smoke crown.\n  float pre=gate(q,.02,.37),g=phase(q,.02,.31);\n  vec2 center=root+vec2(0.,.065);\n  float orb=ball(p,center,.045+.10*g);\n  float halo=ball(p,center,.15+.08*g);\n  v=vec4(mix(vec3(1.,.38,.06),vec3(.90,.98,1.),sat(orb)),sat((orb+.22*halo)*pre));\n  float h=phase(q,.30,1.);\n  if(h>0.&&h<1.){\n   v=over(v,eruptionGround(p,root,phase(q,.30,.53),.77));\n   v=over(v,eruptionColumn(p,root,h,t,1.34,.28,41.));\n   v=over(v,eruptionCloud(p,root,h,t,vec2(.72,1.10),.40));\n   float rise=1.-pow(1.-phase(h,.06,.56),3.);\n   float capPhase=phase(h,.14,1.);\n   vec2 cap=root+vec2(0.,.53+.48*rise);\n   vec4 w=denseSmoke(p,cap,vec2(.16+.49*rise,.10+.14*rise),t,72.);\n   w.a*=smoothstep(.0,.21,capPhase)*(1.-smoothstep(.76,1.,capPhase))*.89;\n   v=over(v,w);\n   float core=ball(p,center,.095)*gate(h,0.,.20);\n   v=over(v,vec4(.95,.99,1.,sat(core)));\n   v=over(v,fl(p,root,phase(q,.30,.96),.77,1.03,43.,16.));\n  }\n  return v;\n }\n // CS262: fissure ignites in a sequence, separate vents burst with alternating heights.\n float cracks=0.;\n for(int i=0;i<4;i++){\n  float k=float(i),x=-.57+k*.38,start=.14+k*.11;\n  vec2 vent=root+vec2(x,0.);\n  float heat=gate(q,max(0.,start-.12),start+.08);\n  float n=lfFB(vec2(p.x*15.,k+7.));\n  float d=seg(p,vent+vec2(-.14,0.),vent+vec2(.15,.025*(n-.5)));\n  cracks=max(cracks,(1.-smoothstep(.008,.035,d))*heat);\n  float h=phase(q,start,min(1.,start+.56));\n  if(h>0.&&h<1.){\n   float tall=.74+.32*mod(k,2.);\n   v=over(v,eruptionGround(p,vent,phase(q,start,start+.20),.27));\n   v=over(v,eruptionColumn(p,vent,h,t,tall,.115,81.+k));\n   v=over(v,eruptionCloud(p,vent,h,t,vec2(.34,tall*.84),.56));\n   v=over(v,fl(p,vent,h,.22,tall*.72,85.+k,5.));\n  }\n }\n return over(v,vec4(firePalette(.87),cracks));\n}\n";
const napalmRollExtra="// CS253 only: a ground-spreading fire cloud with rising turbulent lobes and independent ground smoke.\nvec4 napalmRoll(vec2 p,vec2 root,float h,float t){\n if(h<=0.||h>=1.)return vec4(0.);\n vec2 pos=p-root;\n float spread=1.-pow(1.-phase(h,0.,.27),3.);\n float lift=phase(h,.08,.72);\n float appear=smoothstep(0.,.045,h),endFade=1.-smoothstep(.86,1.,h);\n float flameFade=appear*(1.-smoothstep(.51,.76,h));\n float smokeFade=smoothstep(.055,.19,h)*endFade;\n // Fresh smoke originates at fixed ground locations; age controls rising and widening.\n float groundSmoke=0.;float groundShade=0.;\n for(int i=0;i<12;i++){\n  float k=float(i),lane=mod(k,6.),x=(lane-2.5)/2.5;\n  float age=fract(h*2.35+floor(k/6.)*.5+hash(vec2(lane,15.))*.26);\n  float born=smoothstep(.0,.12,h-age/2.35);\n  vec2 center=vec2(x*.57*spread+.065*sin(age*5.+k),.015+age*.72);\n  vec2 radii=vec2(.11+.105*age,.10+.18*age);\n  vec2 w=(pos-center)/radii;\n  float n=lfFlow(w*3.2+k,vec2(.3,1.8),t);\n  float a0=(1.-smoothstep(.43,1.19,length(w)+(n-.5)*.55))*sin(3.14159*age)*born;\n  groundSmoke=max(groundSmoke,a0);\n  groundShade=max(groundShade,a0*n);\n }\n float groundMask=smoothstep(-.055,.035,pos.y);\n vec4 v=vec4(mix(vec3(.075,.067,.062),vec3(.29,.27,.25),groundShade),groundSmoke*smokeFade*groundMask*.72);\n // Broad contiguous billowing front. Rotate each local noise field as its lobe rises.\n float mass=0.;float heat=0.;float soot=0.;\n for(int i=0;i<9;i++){\n  float k=float(i),side=(k-4.)/4.;\n  float jitter=hash(vec2(k,31.));\n  float age=phase(h,.012*abs(side),.58+.10*jitter);\n  float up=1.-pow(1.-age,2.);\n  vec2 center=vec2(side*(.12+.47*spread),.055+(.22+.35*jitter)*up+.29*lift);\n  vec2 radii=vec2(.105+.17*spread,.085+.20*spread+.07*jitter);\n  vec2 w=(pos-center)/radii;\n  float turn=sign(side+.01)*(age*4.6+.35*jitter);\n  float cs=cos(turn),sn=sin(turn);vec2 rot=vec2(cs*w.x-sn*w.y,sn*w.x+cs*w.y);\n  float n=lfFlow(rot*3.0+k*5.,vec2(.3,1.9),t);\n  float detail=lfFlow(rot*7.0+k*2.,vec2(.1,3.1),t);\n  float shape=1.-smoothstep(.65,1.19,length(w)+(n-.5)*.60+(detail-.5)*.17);\n  float cold=smoothstep(.25,.70,h)* (1.-smoothstep(-.85,.55,w.y));\n  float pockets=smoothstep(.46,.75,n+.15*detail);\n  float fire=shape*(1.-.76*cold);\n  mass=max(mass,fire);\n  heat=max(heat,fire*sat(.26+.68*n+.33*detail-.22*length(w)));\n  soot=max(soot,shape*max(pockets*.62,cold));\n }\n vec3 flameCol=firePalette(sat(heat*1.28));\n // The lifted flame cloud has dark folds, not a collection of opaque orange circles.\n float fireAlpha=mass*flameFade*groundMask;\n v=over(v,vec4(flameCol,fireAlpha));\n float fold=soot*appear*(1.-smoothstep(.74,1.,h))*groundMask;\n v=over(v,vec4(mix(vec3(.055,.047,.042),vec3(.19,.16,.13),sat(heat)),fold*.72));\n // Residual low flames anchor the source of the continuous smoke.\n float n=lfFlow(vec2(pos.x*16.,pos.y*15.),vec2(0.,4.),t);\n float base=(1.-smoothstep(.48,.69,abs(pos.x)))*smoothstep(-.035,.015,pos.y)*(1.-smoothstep(.025,.075+.11*n,pos.y));\n float baseFire=base*appear*(1.-smoothstep(.67,.88,h))*(.5+.5*n);\n v=over(v,vec4(firePalette(.38+.58*n),baseFire));\n return v;\n}\n";
const fireSceneRows=new Set([246,249,252,253,255,257,260,262,263]);
// Reuse the approved CS234 body without changing its own shader or other families.
const fireJetExtra="vec4 spreadingFireJet(vec2 p,float t,float q){"+fireDetails[234].body+"}\n";
const ringActivationBody="if(q<=0.)return vec4(0.);\nfloat tt=fract(t);vec4 v=vec4(0.);\nvec2 center=vec2(0.,-.14),r=vec2(.59,.30),pos=p-center;\nfloat xx=pos.x/r.x;\nfloat arch=sqrt(max(0.,1.-xx*xx));\nfloat drawF=smoothstep(.015,.68,q),finish=smoothstep(.68,.90,q),appear=smoothstep(0.,.055,q);\nfloat angle=fract(atan(pos.y/r.y,pos.x/r.x)/TAU+.5);\nfloat trace=mix(1.-smoothstep(drawF-.055,drawF+.008,angle),1.,finish)*appear;\nfloat baseNoise=lfFlow(pos*12.+vec2(8.,2.),vec2(0.,2.),tt);\nfloat dist=abs(length(pos/r)-1.)*r.y;\nfloat root=(1.-smoothstep(.013,.048,dist+(baseNoise-.5)*.018));\nv=vec4(firePalette(.38+.45*root),root*.95*trace);\nfloat tip=exp(-pow((angle-drawF)/.038,2.))*root*appear*(1.-finish);\nv=over(v,vec4(1.,.96,.76,tip*.92));\nfor(int i=0;i<2;i++){\n float k=float(i),side=k*2.-1.;\n float y0=side*r.y*arch;\n float local=fract(atan(side*arch,xx)/TAU+.5);\n float growth=mix(smoothstep(local-.01,local+.16,drawF),1.,finish)*appear;\n float height=.15+.26*lfFlow(vec2(pos.x*7.+k*17.,4.),vec2(0.,2.5),tt);\n float h=(pos.y-y0)/height;\n float n=lfFlow(vec2(pos.x*10.+k*19.,h*4.),vec2(0.,5.),tt);\n float detail=lfFlow(vec2(pos.x*17.+k*23.,h*6.),vec2(0.,7.),tt);\n float top=.83+.32*n;\n float mask=smoothstep(-.15,.10,h)*(1.-smoothstep(top-.32,top,h))*(1.-smoothstep(.94,1.07,abs(xx)));\n float density=mask*(.38+.72*n)*(.72+.36*detail);\n float heat=sat((1.-sat(h)*.68)*(.60+.55*n+.18*detail));\n vec4 f=vec4(firePalette(heat),sat(density*1.24)*growth);\n v=over(v,f);\n}\nreturn v;\n";
function replaceEffect(source,body){const a=source.indexOf("vec4 effect(vec2 p,float t,float q){");const b=source.lastIndexOf("void main(){");if(a<0||b<a)throw Error("effect source format");return source.slice(0,a)+"vec4 effect(vec2 p,float t,float q){"+body+"}\n"+source.slice(b);}
function activationSource(source,mode){
 if(source.includes("const float p3Form=1.;"))return source.replace("const float p3Form=1.;","const float p3Form=0.;");
 if(source.includes("const float e2Form=1.;"))return source.replace("const float e2Form=1.;","const float e2Form=0.;");
 if(source.includes("float windForm=1.;"))return source.replace("float windForm=1.;","float windForm=smoothstep(0.,.95,q);").replace("float wt=fract(t);","float wt=q>=1.?0.:fract(t);");
 if(source.includes("float waterForm=1.;"))return source.replace("float waterForm=1.;","float waterForm=smoothstep(0.,.95,q);").replace("float wt=fract(t);","float wt=q>=1.?0.:fract(t);");
 if(source.includes("float fieldForm=1.;"))return source.replace("float fieldForm=1.;","float fieldForm=smoothstep(0.,.95,q);").replace("float ft=fract(t);","float ft=q>=1.?0.:fract(t);");
 if(source.includes("float toxFormation=1.;"))return source.replace("float toxFormation=1.;","float toxFormation=smoothstep(0.,.94,q);").replace("float time=fract(t);","float time=q>=1.?0.:fract(t);");
 if(source.includes("float polarFormation=1.;"))return source.replace("float polarFormation=1.;","float polarFormation=smoothstep(0.,.94,q);").replace("float polarTime=fract(t);","float polarTime=q>=1.?0.:fract(t);");
 if(source.includes("const float WEATHER_FORMATION=0.;"))return source.replace("const float WEATHER_FORMATION=0.;","const float WEATHER_FORMATION=1.;").replace("effect(p,uTime,uProgress);}", "effect(p,uProgress>=1.?0.:uTime,uProgress);}");
 const tag="void main(){vec2 p=(vUv-.5)*2.;p*=vec2(max(1.,uAspect),max(1.,1./uAspect));p/=max(.1,uSize);gl_FragColor=";
 const at=source.lastIndexOf(tag);if(at<0||!source.endsWith(";}"))throw Error("unsupported persistent shader entry point");
 const expr=source.slice(at+tag.length,-2).replace(/\buTime\b/g,"stateTime").replace(/\buProgress\b/g,"stateQ");
 const head=source.slice(0,at)+tag.slice(0,-"gl_FragColor=".length);
 let formation="float g=smoothstep(.02,.76,uProgress);p/=mix(.16,1.,g);";
 if(mode==="ring")formation="float g=smoothstep(.015,.76,uProgress);float a=fract(atan(p.y,p.x)/6.2831853+.5);reveal=mix(1.-smoothstep(g-.045,g+.025,a),1.,smoothstep(.76,.94,uProgress));";
 else if(["wall","platform","crystal","roots"].includes(mode))formation="float g=smoothstep(.02,.76,uProgress);p.y=(p.y+.60)/mix(.08,1.,g)-.60;";
 else if(["fog","rain","luminouscloud","nebula","aurora","sundog"].includes(mode))formation="float g=smoothstep(.02,.76,uProgress);p/=vec2(mix(.16,1.,g),mix(.30,1.,g));";
 else if(["wave","slash","resonance"].includes(mode))formation="float g=smoothstep(.02,.76,uProgress);reveal=mix(1.-smoothstep(g-.06,g+.035,clamp((p.x+.95)/1.9,0.,1.)),1.,smoothstep(.76,.94,uProgress));";
 return head+"\nif(uProgress<=0.){gl_FragColor=vec4(0.);return;}float stateTime=fract(uTime),stateQ=fract(uProgress),reveal=1.;"+formation+"\nif(uProgress>=1.){stateTime=0.;stateQ=0.;}vec4 formed="+expr+";formed.a*=smoothstep(0.,.10,uProgress)*reveal;gl_FragColor=formed;}";
}
const weatherRows=new Set([278,279,282,289,299,455,460,470]);
const weatherHelpers="const float WEATHER_FORMATION=0.;\nfloat weatherArrival(float q,float k){return mix(1.,smoothstep(.025+k*.021,.36+k*.024,q),WEATHER_FORMATION);}\nfloat weatherWeather(float q){return mix(1.,smoothstep(.35,.66,q),WEATHER_FORMATION);}\nvec2 weatherCenter(vec2 target,float t,float q,float k){\n float g=weatherArrival(q,k);\n float a=k*2.39996+2.5*g;\n vec2 spiral=vec2(cos(a)*.72,sin(a)*.24)*(1.-g);\n float time=TAU*t;\n vec2 drift=vec2(.085*cos(time+k*1.7),.045*sin(time+k*1.7));\n return target+spiral+drift;\n}\nfloat weatherAlpha(float q,float k){return mix(1.,smoothstep(.015+k*.021,.16+k*.027,q),WEATHER_FORMATION);}\n";
const earthCrystal3="\nfloat e3Cross(vec2 a,vec2 b){return a.x*b.y-a.y*b.x;}\nfloat e3Triangle(vec2 p,vec2 a,vec2 b,vec2 c){\n float sign0=sign(e3Cross(b-a,c-a));\n float v=min(min(sign0*e3Cross(b-a,p-a)/max(length(b-a),.001),sign0*e3Cross(c-b,p-b)/max(length(c-b),.001)),sign0*e3Cross(a-c,p-c)/max(length(a-c),.001));\n return smoothstep(-.012,.012,v);\n}\nfloat e3Quad(vec2 p,vec2 a,vec2 b,vec2 c,vec2 d){return max(e3Triangle(p,a,b,c),e3Triangle(p,a,c,d));}\nvec4 e3Crystal(vec2 p,vec2 a,vec2 b,float width,float seed,float tt,float turn){\n vec2 d=b-a;float l=length(d);if(l<.015||width<.005)return vec4(0.);\n vec2 ax=d/l,side=vec2(-ax.y,ax.x),v=p-a;\n vec2 z=vec2(dot(v,side)/width,dot(v,ax)/l);\n if(abs(z.x)>1.18||z.y<-.02||z.y>1.02)return vec4(0.);\n float tilt=.36*sin(seed+turn);float farx=tilt*.55-.08;\n vec2 bot=vec2(farx,0.),bl=vec2(-.80,.19),tl=vec2(-.96,.73),tip=vec2(farx+.08,1.),tr=vec2(.84,.76),br=vec2(.78,.16);\n vec2 rb=vec2(tilt,.14),rt=vec2(tilt+.07,.77);\n float a0=e3Quad(z,bl,tl,rt,rb),a1=e3Quad(z,rb,rt,tr,br);\n float a2=e3Triangle(z,tl,tip,rt),a3=e3Triangle(z,rt,tip,tr),a4=e3Triangle(z,bot,bl,rb),a5=e3Triangle(z,bot,rb,br);\n float a6=e3Triangle(z,bl,rb,bot);float mask=max(max(max(a0,a1),max(a2,a3)),max(max(a4,a5),a6));\n float grain=fb(z*vec2(6.,19.)+seed);\n vec3 base=mix(vec3(.13,.21,.37),vec3(.36,.30,.58),.35+.22*sin(seed));\n vec3 faceL=mix(base,vec3(.52,.78,.91),.72+.15*cos(turn+seed));\n vec3 faceR=mix(base,vec3(.21,.39,.58),.56+.28*sin(turn+seed));\n vec3 col=base;col=mix(col,faceL,a0);col=mix(col,faceR,a1);col=mix(col,vec3(.65,.86,.96),a2);col=mix(col,vec3(.30,.46,.69),a3);col=mix(col,base*.72,a4);col=mix(col,base*.92,a5);\n float vein=exp(-abs(z.x-tilt-.07*sat(z.y))/.024)*smoothstep(.14,.22,z.y)*(1.-smoothstep(.71,.79,z.y));\n float facetEdge=exp(-abs(z.y-.76-.04*z.x)/.013)*.48+exp(-abs(z.y-.17+.035*z.x)/.014)*.32;\n float shine=exp(-pow((z.y+z.x*.22-.55-.43*cos(tt*TAU+seed))/.075,2.))*.36;\n float inclusion=pow(.5+.5*sin(z.y*55.+z.x*9.+grain*5.),16.)*.10;\n col=mix(col,col*.73,grain*.30);col=mix(col,vec3(.89,.96,1.),sat(vein*.74+facetEdge+shine+inclusion));\n return vec4(col,mask*(.86+.12*sat(vein+facetEdge+shine)));\n}\nvec4 e3Shield(vec2 p,vec2 c,vec2 size,float g,float tt,float seed,float reflect0){\n if(g<=.001)return vec4(0.);vec2 z=(p-c)/max(size*g,vec2(.01));\n vec2 a=vec2(-.64,-.82),b=vec2(-.97,-.26),cc=vec2(-.82,.68),dd=vec2(0.,.98),ee=vec2(.82,.68),ff=vec2(.97,-.26),gg=vec2(.64,-.82),hh=vec2(0.,-1.);\n vec2 ia=vec2(-.48,-.62),ib=vec2(-.72,-.20),ic=vec2(-.61,.50),id=vec2(0.,.73),ie=vec2(.61,.50),ij=vec2(.72,-.20),ik=vec2(.48,-.62),il=vec2(0.,-.76);\n float m=e3Quad(z,ia,ib,ic,id)+e3Quad(z,id,ie,ij,ik)+e3Quad(z,ia,id,ik,il);\n float e0=e3Quad(z,a,b,ib,ia),e1=e3Quad(z,b,cc,ic,ib),e2=e3Quad(z,cc,dd,id,ic),e3=e3Quad(z,dd,ee,ie,id),e4=e3Quad(z,ee,ff,ij,ie),e5=e3Quad(z,ff,gg,ik,ij),e6=e3Quad(z,gg,hh,il,ik),e7=e3Quad(z,hh,a,ia,il);\n float mask=sat(m+e0+e1+e2+e3+e4+e5+e6+e7);\n vec3 col=mix(vec3(.15,.27,.45),vec3(.48,.69,.85),smoothstep(-.6,.7,-z.x+z.y*.33));col=mix(col,vec3(.65,.87,.97),sat(e1+e2));col=mix(col,vec3(.20,.29,.50),sat(e4+e5+e6));col=mix(col,vec3(.38,.49,.74),sat(e0+e3+e7));\n float stripe=exp(-pow((z.x+z.y*.46-1.26*cos(tt*TAU+seed))/.12,2.));\n float joint=exp(-seg(z,ia,id)/.015)*.22+exp(-seg(z,id,ik)/.015)*.26;\n col=mix(col,vec3(.96,.99,1.),sat(stripe*(.32+.48*reflect0)+joint));\n return vec4(col,mask*(.63+.30*sat(e0+e1+e2+e3+e4+e5+e6+e7+stripe)));\n}\n";
const earthLava3="\nvec3 e3LavaMaterial(vec2 p,float tt,float crust){\n float n=e2Noise(p*.88,tt),n2=e2Noise(p*2.2+vec2(7.,3.),tt);\n vec2 z=p+vec2(n-.5,n2-.5)*.85;\n vec2 cell=floor(z),local=fract(z);float best=10.,second=10.;\n for(int i=-1;i<=1;i++){for(int j=-1;j<=1;j++){vec2 k=vec2(float(i),float(j));vec2 a=k+vec2(hash(cell+k),hash(cell+k+vec2(19.,7.)))-local;float r=dot(a,a);if(r<best){second=best;best=r;}else second=min(second,r);}}\n float gap=sqrt(max(second,0.))-sqrt(max(best,0.));\n float molten=1.-smoothstep(.06+.055*(1.-crust),.19+.17*(1.-crust),gap);\n vec3 cold=mix(vec3(.055,.037,.030),vec3(.21,.14,.10),.25+.66*n2);\n vec3 hot=mix(vec3(.68,.055,.008),vec3(1.,.69,.085),sat(n*.72+n2*.40));\n hot=mix(hot,vec3(1.,.91,.31),pow(sat(n2),5.));\n float blend=mix(.56+.44*molten,molten,crust);\n return mix(cold,hot,blend);\n}\nvec4 e3LavaBlob(vec2 p,vec2 c,vec2 r,float tt,float seed,float crust){\n if(min(r.x,r.y)<.004)return vec4(0.);vec2 v=(p-c)/r;float d=length(v);if(d>1.35)return vec4(0.);\n float n=e2Noise(v*3.+seed,tt);float m=1.-smoothstep(.90,1.06,d+(n-.5)*.24);\n vec3 col=e3LavaMaterial(v*2.5+seed,tt,crust);col*=.69+.31*smoothstep(-.95,.62,v.y)+.13*exp(-pow(length(v-vec2(-.32,.36))*3.,2.));\n return vec4(col,m);\n}\nvec4 e3LavaWave(vec2 p,float f,float t){\n if(f<=0.||f>=1.)return vec4(0.);float x=mix(-1.10,1.03,f),rel=p.x-x,e=smoothstep(.0,.10,f)*(1.-smoothstep(.83,1.,f));vec4 v=vec4(0.);\n for(int i=0;i<3;i++){float k=float(i),z=k*.5,y0=-.43-.13*z;\n float n=e2Noise(vec2(rel*6.,p.y*5.+k*3.),t);\n float peak=.46+.31*z;float h=.12+peak*exp(-pow((rel+.18+.08*k)/(.31+.06*z),2.))+.07*(n-.5);\n float mask=smoothstep(y0-.04,y0+.04,p.y)*(1.-smoothstep(y0+h-.025,y0+h+.035,p.y))*smoothstep(-.94,-.72,rel)*(1.-smoothstep(.02,.15,rel));\n if(mask>0.){vec2 uv=vec2(rel*6.+t*1.8,p.y*7.+k*4.);vec3 col=e3LavaMaterial(uv,t,.77);float lip=exp(-abs(p.y-y0-h)/.045);col=mix(col,vec3(1.,.31,.025),lip*.66);col*=.68+.32*z;v=over(v,vec4(col,mask*e));}\n }\n for(int i=0;i<9;i++){float k=float(i),u=fract(t*1.6+hash(vec2(k,4.)));vec2 c=vec2(x-.12-.34*hash(vec2(k,6.))+.12*u,-.32+4.*u*(1.-u)*(.16+.25*hash(vec2(k,9.))));vec4 w=e3LavaBlob(p,c,vec2(.055+.035*hash(vec2(k,11.)),.04),t,k,.36);w.a*=sin(3.14159*u)*e;v=over(v,w);}return v;\n}\nvec4 e3LavaFountain(vec2 p,float q,float t){\n vec2 root=vec2(0.,-.65);float g=phase(q,.29,.48),e=earthEnv(q,.28,.82);if(g<=.001)return earthCharge(p,root,q,.28);\n vec4 v=e3LavaBlob(p,root,vec2(.44*g,.12*g),t,8.,.65);v.a*=e;\n for(int i=0;i<7;i++){float k=float(i),dx=(k-3.)*.21,height=(1.14+.19*cos(k*1.8))*g;\n float f=phase(q,.29+k*.008,.48+k*.01),dist=10.;vec2 prev=root+vec2(dx*.10,0.);\n for(int j=1;j<=10;j++){float u=float(j)/10.*f;vec2 next=root+vec2(dx*u,4.*u*(1.-u)*height);dist=min(dist,seg(p,prev,next));prev=next;}\n float width=(.055+.022*cos(k))*g;float a=1.-smoothstep(width*.58,width,dist);\n if(a>0.){vec3 col=e3LavaMaterial(vec2(p.x*9.+k*2.,p.y*9.-t*3.),t,.28);v=over(v,vec4(col,a*e));}}\n for(int i=0;i<18;i++){float k=float(i),f=fract(t*.95+hash(vec2(k,11.))),a=(hash(vec2(k,13.))-.5)*1.58;vec2 c=root+vec2(a*f,4.*f*(1.-f)*(1.18+.15*cos(k))*g);vec4 w=e3LavaBlob(p,c,vec2(.028+.038*hash(vec2(k,5.)),.038+.022*hash(vec2(k,7.))),t,k,.35);w.a*=sin(3.14159*f)*e;v=over(v,w);}\n return v;\n}\n";
